export function parseCsv(text) {
  if (text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;

  const endField = () => {
    row.push(field);
    field = '';
  };
  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };

  while (i < text.length) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (ch === '"' && field === '') {
      inQuotes = true;
      i += 1;
      continue;
    }
    if (ch === ',') {
      endField();
      i += 1;
      continue;
    }
    if (ch === '\n') {
      endRow();
      i += 1;
      continue;
    }
    if (ch === '\r') {
      endRow();
      i += text[i + 1] === '\n' ? 2 : 1;
      continue;
    }

    field += ch;
    i += 1;
  }

  if (field !== '' || row.length > 0) {
    endRow();
  }

  return rows;
}

export function toObjects(rows) {
  if (!rows || rows.length === 0) return [];

  const header = rows[0];
  const objects = [];

  for (let r = 1; r < rows.length; r += 1) {
    const record = {};
    for (let c = 0; c < header.length; c += 1) {
      const value = rows[r][c];
      record[header[c]] = value === undefined || value === null ? '' : value;
    }
    objects.push(record);
  }

  return objects;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, toObjects } from '../src/csv.js';

test('empty text gives []', () => {
  assert.deepEqual(parseCsv(''), []);
});

test('splits simple rows on commas', () => {
  assert.deepEqual(parseCsv('a,b\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
});

test('handles CRLF line endings', () => {
  assert.deepEqual(parseCsv('a,b\r\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
});

test('a final line break does not add an empty row', () => {
  assert.deepEqual(parseCsv('a,b\n'), [['a', 'b']]);
  assert.deepEqual(parseCsv('a,b\r\n'), [['a', 'b']]);
});

test('quoted fields may contain commas and line breaks', () => {
  assert.deepEqual(parseCsv('"a,b","c\nd"'), [['a,b', 'c\nd']]);
});

test('doubled quotes inside a quoted field mean one quote', () => {
  assert.deepEqual(parseCsv('"say ""hi""",x'), [['say "hi"', 'x']]);
});

test('handles empty fields and trailing commas', () => {
  assert.deepEqual(parseCsv('a,,c'), [['a', '', 'c']]);
  assert.deepEqual(parseCsv('a,"",c'), [['a', '', 'c']]);
  assert.deepEqual(parseCsv('a,'), [['a', '']]);
});

test('parses a full document with quoted newlines', () => {
  const text = 'name,note\r\nAda,"line one\nline two"\r\nBob,"x,y"\r\n';
  assert.deepEqual(parseCsv(text), [
    ['name', 'note'],
    ['Ada', 'line one\nline two'],
    ['Bob', 'x,y'],
  ]);
});

test('toObjects returns [] when there are no rows', () => {
  assert.deepEqual(toObjects([]), []);
});

test('toObjects keys rows by the header', () => {
  assert.deepEqual(
    toObjects([
      ['name', 'age'],
      ['Ada', '36'],
      ['Bob', '40'],
    ]),
    [
      { name: 'Ada', age: '36' },
      { name: 'Bob', age: '40' },
    ],
  );
});

test('toObjects fills missing columns with empty strings', () => {
  assert.deepEqual(
    toObjects([
      ['name', 'age', 'city'],
      ['Ada', '36'],
    ]),
    [{ name: 'Ada', age: '36', city: '' }],
  );
});

test('parseCsv and toObjects work together', () => {
  const rows = parseCsv('name,city\nAda,"Paris, FR"\nBob\n');
  assert.deepEqual(toObjects(rows), [
    { name: 'Ada', city: 'Paris, FR' },
    { name: 'Bob', city: '' },
  ]);
});
